        int ordinal=0;for(Map<String,Object> i:items){String name=raw(i,"name",255),value=raw(i,"value",10000),unit=raw(i,"unit",255),range=raw(i,"referenceRange",2000),abnormal=raw(i,"abnormal",255);require(!name.trim().isEmpty(),422,"检查项目名不能为空");String ev=evidence(a,rid,rev,src,evidencePage(i.get("page")),name,value);String code=safe(i,"itemCode",64);Map<String,Object> d=code.isEmpty()?null:db.one("SELECT item_code,status,standard_name FROM a_medical_item_dictionary WHERE item_code=? AND dictionary_version='2.0.0' AND status<>'retired'",code);require(code.isEmpty()||d!=null,422,"未知的检查项目编码");db.insert("a_health_items",map("report_id",rid,"revision",rev,"item_id",id(),"ordinal",++ordinal,"primary_evidence_id",ev,"evidence_ids",encode(Arrays.asList(ev)),"original_field_name",name,"result_raw",value.isEmpty()?null:value,"unit_raw",unit.isEmpty()?null:unit,"reference_range_raw",range.isEmpty()?null:range,"abnormal_flag_raw",abnormal.isEmpty()?null:abnormal,"field_values","[]","mapping_status",d==null?"unmapped":d.get("status"),"review_status","needs_review","item_code",d==null?null:code,"dictionary_version",d==null?null:"2.0.0","standard_field_name",d==null?null:d.get("standard_name")));}
        if(!conclusion.isEmpty()){String ev=evidence(a,rid,rev,src,evidencePage(body.get("conclusionPage")),"正式体检结论",conclusion);db.insert("a_health_conclusions",map("report_id",rid,"revision",rev,"conclusion_id",id(),"primary_evidence_id",ev,"evidence_ids",encode(Arrays.asList(ev)),"original_field_name","正式体检结论","original_text",conclusion,"completeness","complete","review_status","needs_review"));}
