        db.exec("UPDATE a_extraction_jobs SET status='extracted',updated_at=UTC_TIMESTAMP(6) WHERE report_id=? AND revision=?",rid,rev);audit(a,str(h.get("record_id")),rid,rev,"manual_candidate_saved","人工按原件补录，未执行单位转换");completeness(a,str(h.get("record_id")));return report(a,rid,rev,false);
